/* C API of the Rust port of `wrappers.c`, generated by rust-anything. */
#ifndef WRAPPERS_RS_H
#define WRAPPERS_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

void xa_dump_index(unsigned long index, unsigned int shift);
uint64_t wrap_idr_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_ida_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t wrap_radix_seq(uint64_t seed, int64_t nops_i, int64_t seed2);

/* The same functions under `rust_anything_` names, for shadow runs. */
void rust_anything_xa_dump_index(unsigned long index, unsigned int shift);
uint64_t rust_anything_wrap_idr_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_ida_seq(uint64_t seed, int64_t nops_i, int64_t seed2);
uint64_t rust_anything_wrap_radix_seq(uint64_t seed, int64_t nops_i, int64_t seed2);

#endif /* WRAPPERS_RS_H */
